import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"PDC","description":"","frontmatter":{},"headers":[],"relativePath":"modules/corelib/pdc.md","filePath":"modules/corelib/pdc.md","lastUpdated":0}`),a={name:`modules/corelib/pdc.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="pdc" tabindex="-1">PDC <a class="header-anchor" href="#pdc" aria-label="Permalink to “PDC”">​</a></h1><p>PDC 是 Bukkit <code>PersistentDataContainer</code> 的简称，用于把自定义数据保存到物品、实体、方块状态或玩家等对象上。CoreLib 使用 PDC 保存模块状态，业务模块通过自己的 namespace 写入数据，避免互相覆盖。</p><h2 id="pdc-解决什么问题" tabindex="-1">PDC 解决什么问题 <a class="header-anchor" href="#pdc-解决什么问题" aria-label="Permalink to “PDC 解决什么问题”">​</a></h2><p>如果只把状态写进 Lore，会出现很多问题：</p><ul><li>玩家或其他插件可能修改 Lore。</li><li>多模块同时修改 Lore 时容易互相覆盖。</li><li>解析文本很慢，而且容易受颜色和语言影响。</li><li>无法可靠区分&quot;展示文本&quot;和&quot;真实数据&quot;。</li><li>物品更新或刷新时，文本可能丢失或格式变化。</li></ul><p>PDC 则适合保存真实状态，数据以二进制或结构化形式存储在物品的 NBT 中，不受显示层影响。</p><h2 id="各模块写入的数据" tabindex="-1">各模块写入的数据 <a class="header-anchor" href="#各模块写入的数据" aria-label="Permalink to “各模块写入的数据”">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>写入内容</th><th>说明</th></tr></thead><tbody><tr><td>EmakiItem</td><td>物品 ID、套装 ID、基础属性、技能绑定、版本号</td><td>物品的身份标识和基础配置数据。</td></tr><tr><td>EmakiForge</td><td>锻造层、品质、材料贡献、配方 ID</td><td>锻造结果的结构化记录。</td></tr><tr><td>EmakiStrengthen</td><td>强化星级、锻印状态、保护状态、强化属性、里程碑</td><td>强化进度和惩罚状态。</td></tr><tr><td>EmakiGem</td><td>插槽列表、宝石 ID、宝石等级、升级状态</td><td>宝石系统的完整状态。</td></tr><tr><td>EmakiAttribute</td><td>属性 payload、属性来源标记</td><td>装备提供的属性数值。</td></tr><tr><td>EmakiSkills</td><td>玩家技能槽、技能等级、触发器绑定</td><td>通常保存在玩家数据文件而非物品 PDC。</td></tr><tr><td>EmakiCooking</td><td>世界工位状态、方块实体 PDC 键 <code>emakicooking:station_state</code> 等</td><td>优先写入工位锚点的方块实体 PDC；普通方块回退到 <code>data/stations/</code>，坐标索引用于区块恢复。</td></tr></tbody></table><h2 id="键名规范-不使用点号" tabindex="-1">键名规范：不使用点号 <a class="header-anchor" href="#键名规范-不使用点号" aria-label="Permalink to “键名规范：不使用点号”">​</a></h2><p>Emaki 全系的 PDC 键名一律用下划线 <code>_</code> 连接层级，<strong>不使用点号 <code>.</code></strong>：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>emaki_attribute:item_attributes_source_index</span></span>
<span class="line"><span>emakiforge:forge_quality_id</span></span>
<span class="line"><span>emaki:item_operations</span></span>
<span class="line"><span>emaki:item_state_meta_revision</span></span></code></pre></div><p>原因是 Bukkit 的 <code>YamlConfiguration</code> 把 <code>.</code> 当作路径分隔符。键名一旦含点，第三方插件就无法在 YAML 里表达它——加引号和反斜杠转义都无效，因为拆分发生在 YAML 加载阶段。改用下划线后，这些键可以直接写进任何 Bukkit YAML 配置。</p><div class="warning custom-block"><p class="custom-block-title">这是破坏性变更</p><p>早期版本用点号连接（<code>emakiforge:forge.quality_id</code>）。已存在的物品、玩家和实体上仍是旧键，插件会自动迁移，见下方<a href="#历史键迁移">历史键迁移</a>。</p></div><p>如果你在写扩展模块，分区路径和字段名都不要含点。<code>PdcPartition</code> 会用 <code>_</code> 连接分区与字段，但不会替换你传入的点号。</p><h2 id="历史键迁移" tabindex="-1">历史键迁移 <a class="header-anchor" href="#历史键迁移" aria-label="Permalink to “历史键迁移”">​</a></h2><p>旧键迁移有两条路径，通常不需要你介入。</p><p><strong>懒转换（自动）</strong>：模块读取数据时优先读新键，读不到就回落到历史带点键，命中后就地写入新键并删除旧键。玩家加入时还会对其自身 PDC 做一次主动全量转换，覆盖那些只写不读的镜像键。</p><p><strong>手动命令（加速与排查）</strong>：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakicorelib pdc-convert &lt;players|containers|entities|all&gt; [--dry-run]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>scope</th><th>覆盖范围</th></tr></thead><tbody><tr><td><code>players</code></td><td>在线玩家的背包、装备栏、副手、末影箱（含嵌套潜影盒）以及玩家自身 PDC</td></tr><tr><td><code>containers</code></td><td>已加载区块内容器方块中的物品</td></tr><tr><td><code>entities</code></td><td>已加载区块内的实体自身 PDC，以及掉落物、展示框、生物装备栏上的物品</td></tr><tr><td><code>all</code></td><td>以上全部</td></tr></tbody></table><p>权限 <code>emakicorelib.admin</code>。加 <code>--dry-run</code> 只统计不改写。命令是幂等的，重复执行第二次转换数应为 0。扫描按已加载区块分批进行，不会强制加载区块。</p><div class="important custom-block"><p class="custom-block-title">命令无法触达的范围</p><p>离线玩家的背包与其自身 PDC（数据在 playerdata NBT 文件里）、未加载区块中的容器和实体都扫不到。它们依赖懒转换，在玩家上线或区块加载后读取时自动处理，不需要手工干预。</p></div><div class="danger custom-block"><p class="custom-block-title">配置文件需要手工检查</p><p>转换器只处理 PDC 数据，<strong>不会修改配置文件</strong>。以下两类写法需要你自己更新：</p><ul><li>自建配置里 <code>pdc_match</code> 直接书写的完整键名，如 <code>&quot;emakiforge:forge.quality_id&quot;</code>。</li><li>表达式或匹配器里使用的、由 PDC 键名派生的变量名：<code>pdc_&lt;命名空间&gt;_&lt;键&gt;</code> 与 <code>item_pdc_&lt;命名空间&gt;_&lt;键&gt;</code>。</li></ul><p>EmakiStrengthen 的 Forge 变量是例外，它的点号写法作为别名保留，无需修改。</p></div><h2 id="namespace-原则" tabindex="-1">namespace 原则 <a class="header-anchor" href="#namespace-原则" aria-label="Permalink to “namespace 原则”">​</a></h2><p>每个模块都应该写入自己的命名空间，不要直接覆盖其他模块数据。CoreLib 使用 <code>NamespacedKey</code> 区分不同模块的数据：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>emaki:item_schema_version</span></span>
<span class="line"><span>emakiforge:forge_quality_id</span></span>
<span class="line"><span>emaki_strengthen:strengthen_affix_layer</span></span>
<span class="line"><span>emaki:gem_item_id</span></span>
<span class="line"><span>emaki_attribute:item_attributes_source_index</span></span></code></pre></div><p>这种设计确保：</p><ul><li>强化模块不会意外覆盖宝石数据。</li><li>锻造模块不会破坏物品基础 ID。</li><li>各模块可以独立读写自己的数据。</li><li>清理某个模块状态时不影响其他模块。</li></ul><h2 id="pdc-与-assembly-的关系" tabindex="-1">PDC 与 Assembly 的关系 <a class="header-anchor" href="#pdc-与-assembly-的关系" aria-label="Permalink to “PDC 与 Assembly 的关系”">​</a></h2><p>PDC 保存真实数据，Assembly 负责把这些数据渲染成最终展示。流程：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>模块写入 PDC → CoreLib 读取所有 layer → Assembly 渲染 → 最终 Lore/名称/属性</span></span></code></pre></div><p>这意味着：</p><ul><li>Lore 是&quot;输出&quot;，不是&quot;输入&quot;。不要从 Lore 反推数据。</li><li>修改 Lore 不会改变真实状态。</li><li>刷新物品时，CoreLib 会重新从 PDC 读取并重建展示。</li></ul><h2 id="配置者需要知道什么" tabindex="-1">配置者需要知道什么 <a class="header-anchor" href="#配置者需要知道什么" aria-label="Permalink to “配置者需要知道什么”">​</a></h2><p>大多数时候你不需要手动编辑 PDC。你需要知道的是：</p><ul><li><strong>不要用其他插件随意清理 Emaki 物品的 PDC</strong>。例如某些&quot;物品清理&quot;插件可能会移除自定义 NBT 数据。</li><li><strong>不要把有 PDC 的装备通过不兼容插件重写成全新物品</strong>。例如某些物品编辑插件会创建新 ItemStack 而丢失原有 PDC。</li><li><strong>调试装备时，应使用 inspect / dump 类命令查看真实状态</strong>。不要只看 Lore 判断装备是否正常。</li><li><strong>如果要清除某个模块状态，优先使用模块提供的 clear / reset 命令</strong>。手动删除 PDC key 可能导致数据不一致。</li><li><strong>备份重要装备</strong>。在做破坏性测试前，确保有备份。</li></ul><h2 id="开发者需要注意什么" tabindex="-1">开发者需要注意什么 <a class="header-anchor" href="#开发者需要注意什么" aria-label="Permalink to “开发者需要注意什么”">​</a></h2><p>如果你要写扩展模块或接入 CoreLib：</p><h3 id="使用独立-namespace" tabindex="-1">使用独立 namespace <a class="header-anchor" href="#使用独立-namespace" aria-label="Permalink to “使用独立 namespace”">​</a></h3><div class="language-java"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NamespacedKey key </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NamespacedKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(yourPlugin, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your_data_key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>不要使用其他模块的 namespace 写入数据。</p><h3 id="控制数据大小" tabindex="-1">控制数据大小 <a class="header-anchor" href="#控制数据大小" aria-label="Permalink to “控制数据大小”">​</a></h3><p>不要把大型对象直接无边界写入 PDC。物品 PDC 数据会随物品在网络中传输，过大的数据会影响性能。建议：</p><ul><li>只保存必要的标识和数值。</li><li>复杂数据保存到外部文件，PDC 中只存引用 ID。</li><li>列表数据设置合理上限。</li></ul><h3 id="版本号和迁移" tabindex="-1">版本号和迁移 <a class="header-anchor" href="#版本号和迁移" aria-label="Permalink to “版本号和迁移”">​</a></h3><p>保存结构化数据时要考虑版本号：</p><div class="language-java"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">container.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(versionKey, PersistentDataType.INTEGER, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>当数据格式变化时，通过版本号判断是否需要迁移。CoreLib 的 <code>SnapshotCodec</code> 提供了编解码和版本兼容支持。</p><h3 id="展示由-assembly-统一生成" tabindex="-1">展示由 Assembly 统一生成 <a class="header-anchor" href="#展示由-assembly-统一生成" aria-label="Permalink to “展示由 Assembly 统一生成”">​</a></h3><p>对外展示应由 Assembly / Renderer 统一生成，而不是直接拼 Lore。这样可以：</p><ul><li>保证多模块展示顺序一致。</li><li>避免重复或遗漏。</li><li>支持模板化和国际化。</li></ul><h3 id="读取其他模块数据" tabindex="-1">读取其他模块数据 <a class="header-anchor" href="#读取其他模块数据" aria-label="Permalink to “读取其他模块数据”">​</a></h3><p>优先使用<strong>数据归属方自己的 API 模块</strong>，不要依赖内部 key，也不要再从 CoreLib 找入口：</p><div class="language-java"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// 推荐：通过归属模块的 API 获取</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// 属性 → EmakiAttributeApi（emaki.jiuwu.craft.attribute.api）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EmakiResult&lt;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">Double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; attack </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EmakiAttributeApi.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catalog</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">attributeValue</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(player, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;physical_attack&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// 不推荐：直接读取内部 PDC key</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NamespacedKey internalKey </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NamespacedKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(attributePlugin, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;internal_key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>内部 key 可能在版本更新时变化，API 则保持稳定。</p><h3 id="各类共享-pdc-数据的当前归属" tabindex="-1">各类共享 PDC 数据的当前归属 <a class="header-anchor" href="#各类共享-pdc-数据的当前归属" aria-label="Permalink to “各类共享 PDC 数据的当前归属”">​</a></h3><p>CoreLib 曾经代持过一部分跨模块 PDC 契约，这些契约已下放到各自的 API / 协议模块。新代码请直接使用下表右侧的入口：</p><table tabindex="0"><thead><tr><th>数据</th><th>当前权威入口</th><th>CoreLib 中的遗留入口</th></tr></thead><tbody><tr><td>装备属性 PDC 契约</td><td><code>EmakiAttributeApi</code>（<code>EmakiAttributeApi</code> 模块）</td><td><code>PdcAttributeGateway</code>、<code>EmakiAttributeBridge</code> 已在 CoreLib <code>4.6.7</code> 删除</td></tr><tr><td>装备技能 PDC 读写</td><td><code>EquipmentSkillPdcCodec</code>（<code>EmakiSkillsApi</code> 模块的 <code>emaki.jiuwu.craft.skills.api.pdc</code> 包）</td><td><code>SkillPdcGateway</code> 已在 CoreLib <code>4.6.7</code> 删除</td></tr></tbody></table><p>这些类在 CoreLib 侧已不存在，新代码只能使用上表右侧的入口。</p><h2 id="数据生命周期" tabindex="-1">数据生命周期 <a class="header-anchor" href="#数据生命周期" aria-label="Permalink to “数据生命周期”">​</a></h2><table tabindex="0"><thead><tr><th>事件</th><th>PDC 行为</th></tr></thead><tbody><tr><td>物品创建</td><td>模块写入初始 PDC 数据。</td></tr><tr><td>物品操作（强化/锻造/镶嵌）</td><td>对应模块更新自己的 PDC 数据。</td></tr><tr><td>物品刷新</td><td>CoreLib 读取 PDC，重建展示层。</td></tr><tr><td>物品丢弃/存箱</td><td>PDC 数据随物品保存。</td></tr><tr><td>服务器重启</td><td>PDC 数据随物品持久化，不会丢失。</td></tr><tr><td>物品被其他插件复制</td><td>取决于复制方式，<code>ItemStack.clone()</code> 会保留 PDC。</td></tr><tr><td>物品被 NBT 编辑器修改</td><td>可能破坏数据结构，不建议手动修改。</td></tr></tbody></table>`,61)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};